SELECT q.id AS id, q.code AS code, q.point_code AS point_code, q.kind AS kind, q.level AS level, q.prompt_zh AS prompt_zh, COALESCE(q.prompt_ja, '') AS prompt_ja, q.answer AS answer, q.accepted_json AS accepted_json, COALESCE(q.explain_zh, '') AS explain_zh, COALESCE(q.explain_ja, '') AS explain_ja, q.enabled AS enabled FROM (SELECT a.question_id AS question_id, a.direction AS direction, a.id AS last_wrong_id FROM (SELECT question_id, direction, mid, SUM(CASE WHEN correct = 1 AND hinted = 0 AND id > mid THEN 1 ELSE 0 END) AS good FROM (SELECT id, question_id, direction, correct, hinted, MAX(CASE WHEN correct = 0 THEN id END) OVER (PARTITION BY question_id, direction) AS mid FROM dictation_question_attempt WHERE learner = :learner AND subject_id = CAST(:subject_id AS INTEGER)) WHERE mid IS NOT NULL GROUP BY question_id, direction, mid) g JOIN dictation_question_attempt a ON a.id = g.mid WHERE g.good < 2) w JOIN dictation_question q ON q.id = w.question_id AND q.subject_id = CAST(:subject_id AS INTEGER) WHERE w.direction = :direction AND q.kind = :direction AND q.enabled = 1 AND (:level = '' OR q.level = :level) AND instr(',' || :asked_ids || ',', ',' || q.id || ',') = 0 ORDER BY w.last_wrong_id DESC LIMIT 1
